            'id': row['id'],
            'text': row['text'],
            'speaker': row['speaker'],
            'type': row['type'],
        })
edges=[]
with open('input/edges.csv', newline='', encoding='utf-8') as f:
    reader=csv.DictReader(f)
    for row in reader:
        edges.append({
            'source': row['source'],
            'target': row['target'],
            'text': row['text'],
        })
obj={'nodes': nodes, 'edges': edges}
Path('output/graph.json').write_text(json.dumps(obj, ensure_ascii=False, indent=2), encoding='utf-8')
print('wrote', len(nodes), 'nodes', len(edges), 'edges')
